<script setup>
import { ref } from 'vue'; import { useRoute, useRouter, RouterLink } from 'vue-router'; import { login } from '../api'; import { toChineseErrorMessage } from '../api/status'
const router = useRouter(); const route = useRoute(); const form = ref({ username: '', password: '' }); const error = ref(route.query.registered ? '注册成功，请登录' : ''); const loading = ref(false)
async function submit() { error.value = ''; loading.value = true; try { const user = await login(form.value); const defaultRoute = String(user?.role || '').toLowerCase() === 'admin' ? '/admin' : '/'; router.push(route.query.redirect || defaultRoute) } catch (e) { error.value = toChineseErrorMessage(e) } finally { loading.value = false } }
</script>
<template><div class="auth-page"><div class="auth-image"><div><p class="eyebrow">WELCOME BACK</p><h1>回来，继续<br /><i>记录你的校园。</i></h1></div></div><div class="auth-panel"><RouterLink to="/" class="brand auth-brand"><span class="brand-mark">拾</span><span>拾光 <em>Campus</em></span></RouterLink><div class="auth-content"><p class="eyebrow">SIGN IN</p><h2>登录拾光</h2><p class="auth-description">把今天的光，留在你的校园故事里。</p><form @submit.prevent="submit"><label>用户名<input v-model="form.username" required placeholder="输入用户名" /></label><label>密码<input v-model="form.password" required type="password" placeholder="输入密码" /></label><p v-if="error" class="form-error">{{ error }}</p><button class="dark-button full" :disabled="loading">{{ loading ? '登录中...' : '登录' }}</button></form><p class="auth-switch">还没有账号？<RouterLink to="/register">注册一个</RouterLink></p></div></div></div></template>
